-- chair-step: inverse of read_lane_v2_b2_21_agent_drift_alert — un-enrolls agent.drift_alert from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'drift_alert' and is_active);
select iam.apply_rls('agent', 'drift_alert', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'drift_alert' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'drift_alert' and is_active));
